function buildForest(w){const a=w.a,d=w.details,steel=a.plain(0x707c6f),leafCanvas=document.createElement('canvas');leafCanvas.width=leafCanvas.height=128;const c=leafCanvas.getContext('2d');let seed=17;const r=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<650;i++){const y=10+r()*115,x=64+(r()-.5)*(15+y*.8);c.fillStyle=['#314b35','#4a6242','#667853','#263d30'][i%4];c.fillRect(x,y,3,5);}const map=new T.CanvasTexture(leafCanvas);map.colorSpace=T.SRGBColorSpace;const leaves=new T.MeshStandardMaterial({map,alphaTest:.4,side:T.DoubleSide,roughness:1}),card=new T.PlaneGeometry(1,1);for(let i=0;i<85;i++){const side=i%3,x=side===0?((i%25)*2.2<6?-42:-29)-i%7:side===1?29+i%7:-26+(i%26)*2,z=side===2?(x>-12?49:35)+i%9:-20+(i%25)*2.2,h=6+(i*17%9);if(side===1&&z>24)continue;d.box(a.get('wood',0x5e5142),x,h/2,z,.35,h,.35);for(let n=0;n<3;n++)d.add(card,leaves,x,h*.56,z,4.5,h*.95,1,0,n*Math.PI/3,0);}for(const x of[-23,23])for(let z=-21;z<31;z+=3){if(x===-23&&z<-15||x===23&&z>24)continue;d.box(steel,x,1,z,.075,2,.075);d.box(steel,x,1.75,z+1.5,.05,.05,3);}}
